package in.tallybridge.app;

import android.app.*;import android.appwidget.*;import android.content.*;import android.content.res.Configuration;import android.net.Uri;import android.os.Bundle;import android.view.View;import android.widget.RemoteViews;import org.json.*;import java.util.*;import java.util.concurrent.*;

/** Scrollable Order Desk widget: every pending order shows party, products and quantities. */
public final class OrdersWidget extends AppWidgetProvider{
 private static final String ACTION_REFRESH="in.tallybridge.app.WIDGET_REFRESH_ORDERS", PREF="orders_widget_state";
 private static final ExecutorService IO=Executors.newSingleThreadExecutor();
 @Override public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)paint(c,m,id);refreshAsync(c);}
 @Override public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,Bundle opts){paint(c,m,id);}
 @Override public void onReceive(Context c,Intent i){super.onReceive(c,i);if(ACTION_REFRESH.equals(i.getAction()))refreshAsync(c);}
 public static void refreshAll(Context c){refreshAsync(c.getApplicationContext());}
 private static boolean dark(Context c){String mode=c.getSharedPreferences("appearance",Context.MODE_PRIVATE).getString("mode","System");return mode.equals("Dark")||(mode.equals("System")&&(c.getResources().getConfiguration().uiMode&Configuration.UI_MODE_NIGHT_MASK)==Configuration.UI_MODE_NIGHT_YES);}
 private static boolean compact(AppWidgetManager m,int id){Bundle o=m.getAppWidgetOptions(id);return o.getInt(AppWidgetManager.OPTION_APPWIDGET_MIN_HEIGHT,220)<185;}
 private static int layout(Context c,AppWidgetManager m,int id){boolean d=dark(c);if(compact(m,id))return d?R.layout.orders_widget_compact_dark:R.layout.orders_widget_compact;return d?R.layout.orders_widget_dark:R.layout.orders_widget;}
 private static PendingIntent activity(Context c,int req,Intent i){return PendingIntent.getActivity(c,req,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static PendingIntent template(Context c,int req,Intent i){return PendingIntent.getActivity(c,req,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_MUTABLE);}
 private static PendingIntent refresh(Context c,int id){Intent i=new Intent(c,OrdersWidget.class).setAction(ACTION_REFRESH).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);return PendingIntent.getBroadcast(c,6100+id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 private static void paint(Context c,AppWidgetManager m,int id){SharedPreferences p=c.getSharedPreferences(PREF,Context.MODE_PRIVATE);int count=p.getInt("count",0);boolean isCompact=compact(m,id);RemoteViews v=new RemoteViews(c.getPackageName(),layout(c,m,id));v.setTextViewText(R.id.widget_pending,String.valueOf(count));v.setTextViewText(R.id.widget_mode,p.getBoolean("offline",true)?"SAVED":"SYNCED");v.setOnClickPendingIntent(R.id.widget_refresh,refresh(c,id));v.setOnClickPendingIntent(R.id.widget_add,activity(c,6200+id,new Intent(c,OrdersActivity.class).setAction(OrdersActivity.ACTION_NEW)));v.setOnClickPendingIntent(R.id.widget_open,activity(c,6300+id,new Intent(c,OrdersActivity.class)));
  if(isCompact){String first="No pending orders";try{JSONArray a=new JSONArray(p.getString("rows","[]"));if(a.length()>0){JSONObject x=a.optJSONObject(0);first=x.optString("party")+(x.optString("detail").isEmpty()?"":" • "+x.optString("detail"));}}catch(Exception ignored){}v.setTextViewText(R.id.widget_party1,first);}
  else{Intent svc=new Intent(c,OrdersWidgetService.class).putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);svc.setData(Uri.parse(svc.toUri(Intent.URI_INTENT_SCHEME)));v.setRemoteAdapter(R.id.widget_orders_list,svc);v.setEmptyView(R.id.widget_orders_list,R.id.widget_empty);v.setPendingIntentTemplate(R.id.widget_orders_list,template(c,6400+id,new Intent(c,OrdersActivity.class)));}
  m.updateAppWidget(id,v);if(!isCompact)m.notifyAppWidgetViewDataChanged(id,R.id.widget_orders_list);
 }
 private static String qty(double n){if(Math.rint(n)==n)return String.valueOf((long)n);return String.format(Locale.US,"%.2f",n).replaceAll("0+$","").replaceAll("\\.$","");}
 private static String orderDetail(JSONObject o){JSONArray items=o.optJSONArray("items");StringBuilder b=new StringBuilder();if(items!=null)for(int j=0;j<items.length();j++){JSONObject x=items.optJSONObject(j);if(x==null)continue;if(b.length()>0)b.append(" • ");String unit=x.optString("unit").trim();b.append(qty(x.optDouble("quantity")));if(!unit.isEmpty())b.append(' ').append(unit);b.append(' ').append(x.optString("name","Item"));}if(b.length()==0&&o.optBoolean("photoOrder"))b.append("Photo order");return b.toString();}
 private static void cache(Context c,JSONObject data,boolean offline){JSONArray pending=data.optJSONArray("pending"),rows=new JSONArray();if(pending!=null)for(int i=0;i<pending.length();i++){JSONObject o=pending.optJSONObject(i);if(o==null)continue;try{rows.put(new JSONObject().put("id",o.optString("id")).put("party",o.optString("buyer","Order")).put("number",o.optString("number")).put("detail",orderDetail(o)));}catch(Exception ignored){}}c.getSharedPreferences(PREF,Context.MODE_PRIVATE).edit().putInt("count",pending==null?0:pending.length()).putBoolean("offline",offline).putString("rows",rows.toString()).putLong("updated",System.currentTimeMillis()).apply();}
 private static void updateAll(Context c){AppWidgetManager m=AppWidgetManager.getInstance(c);int[] ids=m.getAppWidgetIds(new ComponentName(c,OrdersWidget.class));for(int id:ids)paint(c,m,id);}
 private static void refreshAsync(Context c){Context app=c.getApplicationContext();IO.execute(()->{boolean offline=true;try{CryptoStore secure=new CryptoStore(app);OfflineOrdersStore orders=new OfflineOrdersStore(secure);JSONObject local=orders.list();cache(app,local,true);updateAll(app);if(!secure.get("base").isEmpty()&&!secure.get("device").isEmpty()){try{JSONObject synced=orders.sync(new BridgeApi(secure));cache(app,synced,false);offline=false;}catch(Exception ignored){cache(app,orders.list(),true);}}}catch(Exception ignored){}finally{updateAll(app);}});}
}
